// Generated by npm run generate from fonts/manifest.json (written by npm run generate:fonts).
// Node-only loader for Satori / next/og renderers (#99). Edge runtimes copy fonts/* at build time and check
// fontManifest.outputs themselves; see docs/installation.md.
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {fontManifest,ogFonts,type OgFont,type OgFontAsset} from './index.js';

export interface LoadedOgFont { readonly name: OgFont['name']; readonly weight: OgFont['weight']; readonly style: 'normal'; readonly data: Buffer }

// One literal URL per face. Turbopack (the Next 16 default) only traces literal asset URLs; it emits each face next to the
// server output, so the route also works from `output: 'standalone'`. Never build these paths from a variable: a template
// URL made Turbopack read one file for every face.
const fontUrls: Readonly<Record<OgFontAsset, () => URL>> = {
  "BloxwapSans.ttf": () => new URL('../fonts/BloxwapSans.ttf', import.meta.url),
  "BloxwapSans-Medium.ttf": () => new URL('../fonts/BloxwapSans-Medium.ttf', import.meta.url),
  "BloxwapSans-Bold.ttf": () => new URL('../fonts/BloxwapSans-Bold.ttf', import.meta.url),
  "BloxwapSans-Black.ttf": () => new URL('../fonts/BloxwapSans-Black.ttf', import.meta.url),
  "BloxwapMono-Medium.ttf": () => new URL('../fonts/BloxwapMono-Medium.ttf', import.meta.url),
};

// webpack (`next build --webpack`) turns the URLs above into /_next/static/media/... paths that fs cannot open. Read the
// package's own fonts/ directory instead; webpack fixes import.meta.url to this file in node_modules at build time.
function fontLocation(asset: OgFontAsset): URL | string {
  const url = fontUrls[asset]();
  return url.protocol === 'file:' ? url : join(dirname(fileURLToPath(import.meta.url)), '..', 'fonts', asset);
}

/** Reads one packaged TTF and throws unless its SHA-256 matches the manifest. */
export async function readOgFont(asset: OgFontAsset): Promise<Buffer> {
  const expected = fontManifest.outputs[asset];
  if (!expected || !Object.hasOwn(fontUrls, asset)) throw new Error(`@bloxwap/hig-og-fonts does not ship ${String(asset)}`);
  const data = await readFile(fontLocation(asset));
  const actual = createHash('sha256').update(data).digest('hex');
  if (actual !== expected) throw new Error(`@bloxwap/hig-og-fonts ${asset}: SHA-256 ${actual} does not match the manifest (${expected})`);
  return data;
}

/** Verified fonts in the shape Satori and next/og ImageResponse take: {name, data, weight, style}. */
export async function loadOgFonts(faces: ReadonlyArray<OgFont> = ogFonts): Promise<LoadedOgFont[]> {
  return Promise.all(faces.map(async face => ({name: face.name, weight: face.weight, style: face.style, data: await readOgFont(face.asset)})));
}
